WITH valid AS (SELECT *, CAST(is_flagged AS INT) is_flagged_flag FROM transactions WHERE txn_time > TIMESTAMP '2023-07-25 15:00:00'), with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY amount DESC, id) event_seq, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_time DESC, id) row_seq, SUM(amount) OVER (PARTITION BY account_id ORDER BY is_flagged_flag, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_amount FROM valid), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM with_windows), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), filtered AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged_flag, event_seq, cumulative_amount, is_new_burst, burst_id, CEIL(event_seq) event_seq_whole FROM sessions_transactions WHERE merchant IS DISTINCT FROM '7-Eleven'), with_dims AS (SELECT s.id, s.account_id, s.txn_type, s.txn_time, s.merchant, s.is_flagged_flag, s.event_seq, a.status FROM filtered s LEFT JOIN accounts a ON s.account_id = a.id) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, COUNT(DISTINCT id) AS distinct_ids, MIN(txn_time) AS started_at, SUM(CASE WHEN txn_type = 'REFUND' THEN event_seq ELSE 0 END) AS refund_event_seq, COUNT(DISTINCT merchant) AS distinct_merchants, PERCENTILE_APPROX(event_seq, 0.9) AS event_seq_p90 FROM with_dims GROUP BY ROLLUP (DATE_TRUNC('YEAR', txn_time))
